import XCTest
import Foundation
@testable import AtlasPCAVerify

/// The RSA, big-number and RSASSA-PSS certificate code against real implementations on edge inputs. Verdicts in
/// test-data/attest-crypto-differential.json come from OpenSSL (signatures, `openssl verify`) and Python integers (modular powers),
/// regenerated by tools/pca-audit/swift-mutate/gen-attest-crypto-differential.py. A row marked strict is one this verifier refuses on
/// purpose although OpenSSL accepts it; accepting anything OpenSSL refuses always fails.
final class AttestCryptoDifferentialTests: XCTestCase {
    static let doc: JSONValue = (try? K042.json("attest-crypto-differential.json")) ?? .null

    private func flag(_ r: JSONValue, _ k: String) -> Bool {
        if case .bool(true)? = r.get(k) { return true }
        return false
    }

    /// Bytes of a hex integer as Python's format(x, 'x') prints it (odd lengths are left-padded).
    private func num(_ s: String?) -> [UInt8] {
        let t = s ?? ""
        guard let b = ACrypto.unhex(t.count % 2 == 0 ? t : "0" + t) else {
            XCTFail("bad hex in the fixture: \(t)")
            return []
        }
        return b
    }

    private func hashOf(_ s: String?) -> AHash? {
        switch s {
        case "sha1": return .sha1
        case "sha256": return .sha256
        case "sha384": return .sha384
        case "sha512": return .sha512
        default: return nil
        }
    }

    func testRsaSignaturesMatchOpenSSL() throws {
        let rows = try XCTUnwrap(Self.doc.get("rsa")?.asArray)
        let keys = try XCTUnwrap(Self.doc.get("keys"))
        var kinds = Set<String>()
        for r in rows {
            let kind = r.get("kind")?.asString ?? ""
            let keyId = r.get("key")?.asString ?? ""
            let key = try XCTUnwrap(keys.get(keyId))
            let n = num(key.get("n")?.asString), e = num(key.get("e")?.asString)
            let hash = try XCTUnwrap(hashOf(r.get("hash")?.asString))
            let msg = num(r.get("msg")?.asString), sig = num(r.get("sig")?.asString)
            var got = false
            if kind == "pss" {
                guard case let .int(salt)? = r.get("salt") else { return XCTFail("salt missing") }
                got = ACrypto.rsaVerifyPSS(n: n, e: e, hash: hash, message: msg, sig: sig, saltLength: Int(salt))
            } else {
                got = ACrypto.rsaVerifyPKCS1(n: n, e: e, hash: hash, message: msg, sig: sig)
            }
            let openssl = flag(r, "ok")
            kinds.insert(kind + (openssl ? "+" : "-"))
            let label = "\(kind) key \(keyId) \(r.get("hash")?.asString ?? ""): \(r.get("why")?.asString ?? "")"
            if flag(r, "strict") { XCTAssertFalse(got, label) } else { XCTAssertEqual(got, openssl, label) }
        }
        // both verdicts of both schemes were exercised, so the table cannot pass empty or one-sided
        XCTAssertEqual(kinds, ["pss+", "pss-", "pkcs1+", "pkcs1-"])
        XCTAssertGreaterThan(rows.count, 500)
    }

    func testModularPowersMatchPython() throws {
        let rows = try XCTUnwrap(Self.doc.get("modpow")?.asArray)
        XCTAssertGreaterThan(rows.count, 2000)
        for r in rows {
            let b = num(r.get("b")?.asString), e = num(r.get("e")?.asString), m = num(r.get("m")?.asString), want = num(r.get("r")?.asString)
            let base = BigNat(bytes: b), mod = BigNat(bytes: m)
            let got = BigNat.modPowOdd(base: base, exp: BigNat(bytes: e), mod: mod)
            let label = "\(r.get("b")?.asString ?? "")^\(r.get("e")?.asString ?? "") mod \(r.get("m")?.asString ?? "")"
            XCTAssertEqual(got, BigNat(bytes: want), label)
            let k = (mod.bitLength + 7) / 8
            let padded = [UInt8](repeating: 0, count: k - want.drop { $0 == 0 }.count) + want.drop { $0 == 0 }
            XCTAssertEqual(got.bytes(length: k), padded, label)
            XCTAssertTrue(base < mod, label)
            XCTAssertFalse(mod < base, label)
        }
    }

    func testPssCertificatesMatchOpenSSL() throws {
        let rows = try XCTUnwrap(Self.doc.get("certs")?.asArray)
        let root = try Cert.parseDER(num(Self.doc.get("root")?.asString))
        XCTAssertTrue(rows.contains { flag($0, "openssl") })
        XCTAssertTrue(rows.contains { !flag($0, "openssl") })
        for r in rows {
            let issuer = try r.get("root")?.asString.map { try Cert.parseDER(num($0)) } ?? root
            let got = (try? Cert.parseDER(num(r.get("der")?.asString))).map { Cert.sigOKBy($0, issuer) } ?? false
            let label = r.get("why")?.asString ?? ""
            if flag(r, "strict") { XCTAssertFalse(got, label) } else { XCTAssertEqual(got, flag(r, "openssl"), label) }
        }
    }

    /// modPowOdd is only sound for odd moduli and an RSA modulus can come from a certificate an attacker supplies, so an even one must
    /// never reach it: `rsaPublic`, its only caller, refuses first, through both verifiers and through a certificate's key.
    func testAnEvenModulusIsRefusedBeforeTheArithmetic() throws {
        let key = try XCTUnwrap(Self.doc.get("keys")?.get("even"))
        let n = num(key.get("n")?.asString), e = num(key.get("e")?.asString)
        XCTAssertEqual(n.last.map { $0 & 1 }, 0)
        var sig = [UInt8](repeating: 0, count: n.count)
        sig[n.count - 1] = 2
        XCTAssertNil(ACrypto.rsaPublic(n: n, e: e, sig: sig))
        XCTAssertFalse(ACrypto.rsaVerifyPSS(n: n, e: e, hash: .sha256, message: [1], sig: sig, saltLength: 32))
        XCTAssertFalse(ACrypto.rsaVerifyPKCS1(n: n, e: e, hash: .sha256, message: [1], sig: sig))
        // the same modulus one higher reaches the arithmetic, so the refusal above is the parity check and nothing else
        var odd = n
        odd[odd.count - 1] |= 1
        XCTAssertNotNil(ACrypto.rsaPublic(n: odd, e: e, sig: sig))
    }
}
